    "./components/**/*.{js,jsx,ts,tsx}",
  ],
  theme: {
    extend: {},
  },
  plugins: [
    require('@catppuccin/tailwindcss')({
      prefix: 'ctp',
      defaultFlavour: 'mocha',
    }),
  ],
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  swcMinify: true,
  // Enable static export for Electron
  output: 'export',
  // Optional: Change the output directory `out` -> `dist`
  distDir: 'dist',
  // Fix for @catppuccin/tailwindcss module resolution
  webpack: (config) => {
    config.resolve.fallback = { fs: false };
    return config;
  }
}

module.exports = nextConfig

@import "tailwindcss/base";
@import "tailwindcss/components";
@import "tailwindcss/utilities";

/* Import Catppuccin Mocha theme */
@import "@catppuccin/tailwindcss/mocha.css";

/* Custom global styles */
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #1e1e2e; /* Catppuccin Mocha base */
  color: #cdd6f4; /* Catppuccin Mocha text */
}

/* Custom button styles using Catppuccin colors */
.btn {
  @apply px-4 py-2 rounded-md font-medium transition-all duration-200 ease-in-out;
}

.btn:focus {
  @apply outline-none ring-2 ring-ctp-mauve-400 ring-opacity-50;
}

import '../styles/globals.css';

function MyApp({ Component, pageProps }) {
  return <Component {...pageProps} />;
}

export default MyApp;

import React, { useState } from 'react';

export default function Home() {
  const [clickCount, setClickCount] = useState(0);

  const handleButtonClick = (color) => {
    setClickCount(clickCount + 1);
    console.log(`Clicked ${color} button!`);
  };

  return (
    <div className="min-h-screen bg-ctp-base flex flex-col items-center justify-center p-4">
      <div className="max-w-2xl w-full space-y-8">
        {/* Header */}
        <div className="text-center">
          <h1 className="text-4xl md:text-6xl font-bold text-ctp-text mb-4">
            Hello World
          </h1>
          <p className="text-xl text-ctp-subtext0">
            Welcome to Electron + Next.js with Catppuccin Theme
          </p>
        </div>

        {/* Stats */}
        <div className="bg-ctp-mantle rounded-lg p-6 text-center">
          <p className="text-ctp-text">
            Buttons clicked: <span className="font-bold text-ctp-green">{clickCount}</span>
          </p>
        </div>

        {/* Buttons Section */}
        <div className="space-y-6">
          <h2 className="text-2xl font-semibold text-ctp-text text-center">
            Themed Buttons
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Red Button */}
            <button
              onClick={() => handleButtonClick('red')}
              className="btn bg-ctp-red-400 hover:bg-ctp-red-500 text-ctp-base"
            >
              Red Button
            </button>

            {/* Green Button */}
            <button
              onClick={() => handleButtonClick('green')}
              className="btn bg-ctp-green-400 hover:bg-ctp-green-500 text-ctp-base"
            >
              Green Button
            </button>

            {/* Blue Button */}
            <button
              onClick={() => handleButtonClick('blue')}
              className="btn bg-ctp-blue-400 hover:bg-ctp-blue-500 text-ctp-base"
            >
              Blue Button
            </button>

            {/* Yellow Button */}
            <button
              onClick={() => handleButtonClick('yellow')}
              className="btn bg-ctp-yellow-400 hover:bg-ctp-yellow-500 text-ctp-base"
            >
              Yellow Button
            </button>
          </div>

          {/* Gradient Button */}
          <div className="pt-4">
            <button
              onClick={() => handleButtonClick('gradient')}
              className="w-full btn bg-linear-50 from-ctp-red-400 to-ctp-mauve-400 hover:from-ctp-red-500 hover:to-ctp-mauve-500 text-ctp-base"
            >
              Gradient Button
            </button>
          </div>
        </div>

        {/* Catppuccin Info */}
        <div className="text-center text-ctp-subtext1 text-sm mt-8">
          <p>Using Catppuccin Mocha theme with soothing pastel colors</p>
        </div>
      </div>
    </div>
  );
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  // Enable static export for Electron
  output: 'export',
  // Optional: Change the output directory `out` -> `dist`
  distDir: 'dist',
